//! 单实例守卫：同一用户会话里只允许一个 scrcpy-pad 进程跑。
//! (docs as designed)

use std::path::PathBuf;

/// 唯一实例的名字。改语义时要一起改版本号 ...
const LOCK_NAME: &str = "scrcpy-pad-single-instance-v1";

/// 已有一个实例在跑(带一句可直接展示给用户的人话说明)。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AlreadyRunning {
    pub detail: String,
}

impl std::fmt::Display for AlreadyRunning {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.detail)
    }
}

/// "唯一实例"凭据。拿到它 = 本进程可以继续跑;drop 或进程结束时由内核释放。
///
/// **不需要手工清理**:把守卫绑在 main 里活到进程结束,即使被任务管理器强杀,
/// Windows 的互斥体/POSIX 的文件锁都会由内核回收 —— "守卫自己不能变成残留"。
pub struct Guard {
    inner: imp::Inner,
}

impl Guard {
    /// 平台侧是否退化成"无法判定"(互斥体/锁文件创建失败)。
    /// 退化时放行但已经打过警告 —— 宁可漏拦一次,也不能让程序完全起不来。
    pub fn degraded(&self) -> bool {
        self.inner.degraded
    }
}

/// 尝试成为唯一实例。
pub fn acquire() -> Result<Guard, AlreadyRunning> {
    imp::acquire_named(LOCK_NAME).map(|inner| Guard { inner })
}
