        handle: HANDLE,
        pub degraded: bool,
    }

    impl Drop for Inner {
        fn drop(&mut self) {
            if !self.handle.is_null() {
                // SAFETY: 句柄由本进程的 CreateMutexW 创建且只在这里关一次。
                unsafe { CloseHandle(self.handle) };
            }
        }
    }

    fn wide(name: &str) -> Vec<u16> {
        name.encode_utf16().chain(std::iter::once(0)).collect()
    }

    pub fn acquire_named(name: &str) -> Result<Inner, AlreadyRunning> {
        let wname = wide(name);
        // SAFETY: ...
        let handle = unsafe { CreateMutexW(std::ptr::null(), 0, wname.as_ptr()) };
        // GetLastError 必须紧接在 CreateMutexW 之后读:任何其它 API 调用都可能覆盖它
        let last = unsafe { GetLastError() };
        if handle.is_null() {
            let e = std::io::Error::last_os_error();
            crate::diag_warn!("instance", "无法创建单实例互斥体 {name:?}: {e} —— 本次不做重复实例拦截");
            eprintln!("[instance] 无法创建单实例互斥体: {e} —— 本次不做重复实例拦截");
            return Ok(Inner { handle, degraded: true });
        }
        if last == ERROR_ALREADY_EXISTS {
            // 自己已经拿到一个句柄,先关掉:真正持有者是那个仍在跑的实例
            // SAFETY: 同上
            unsafe { CloseHandle(handle) };
            return Err(AlreadyRunning {
