/// 默认轨迹最多保留几份(含本次这一份)。
const MAX_TRACE_FILES: usize = 3;

/// 只认默认命名的轨迹文件:`trace-<纯数字>.jsonl`。
/// 判名字而不是判扩展名:配置目录里还有 profile.yaml / look.json / 日志,
/// 而**用户手写的文件绝不能被我们删掉**。
fn trace_stamp(name: &str) -> Option<u64> {
    let mid = name.strip_prefix("trace-")?.strip_suffix(".jsonl")?;
    if mid.is_empty() || !mid.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    mid.parse().ok()
}

/// 删掉最旧的默认轨迹文件,使**含本次**的总数不超过 [`MAX_TRACE_FILES`]。
///
/// 只删配置目录里符合 `trace-<秒>.jsonl` 的文件的**最旧的那几个**;
/// 本次要写的 `current` 永远不在删除范围内(同一秒内重启时它可能已经存在)。
fn prune_old_traces(current: &Path) {
    let dir = current.parent().unwrap_or_else(|| Path::new("."));
    let Ok(rd) = std::fs::read_dir(dir) else { return };  // 读不到就跳过:默认轨迹不该因为清理失败而开不了
    let mut old: Vec<(u64, PathBuf)> = Vec::new();
    for entry in rd.flatten() {
        let path = entry.path();
        if path == current { continue; }
        let Some(name) = path.file_name().and_then(|n| n.to_str()) else { continue };
        let Some(stamp) = trace_stamp(name) else { continue };
        old.push((stamp, path));
    }
    // 旧的在前;时间戳相同时按文件名定序,保证删哪个是确定的(不靠目录顺序)
    old.sort();
    // 留下的空位 = 上限 - 1(本次这一份)
    let keep = MAX_TRACE_FILES.saturating_sub(1);
    while old.len() > keep {
        let (_, path) = old.remove(0);
        if let Err(e) = std::fs::remove_file(&path) {
            // 删不掉(被占用/只读)不是错误:轨迹本身照写,只是总量可能多几条
            crate::diag_debug!("trace", "无法删除旧轨迹 {}: {e}", path.display());
        }
    }
}
