// ============================ 其它平台:文件锁 + pid ============================
#[cfg(not(windows))]
mod imp {
    use std::fs::{File, OpenOptions, TryLockError};
    use std::io::{Read, Seek, SeekFrom, Write};
    use std::path::{Path, PathBuf};

    use super::AlreadyRunning;

    pub(super) struct Inner {
        /// 锁文件句柄。**只持有不读**:`File` 一被 drop,文件锁就释放了,
        /// 所以它必须活到进程结束 —— "没被读过"是刻意的,不是漏写。
        file: Option<File>,
    }

    impl Inner {
        pub(super) fn release(&mut self) {
            // drop 掉句柄 = 释放文件锁(内核还会在进程结束时兜底释放)。
            self.file = None;
        }
    }

    /// 锁文件路径:与配置同目录,便于"看一眼是谁占着"。
    pub(super) fn lock_path(name: &str) -> PathBuf {
        crate::app::config_dir().join(format!("{name}.lock"))
    }

    pub(super) fn acquire_named(name: &str) -> Result<Inner, AlreadyRunning> {
        acquire_path(&lock_path(name))
    }

    fn acquire_path(path: &Path) -> Result<Inner, AlreadyRunning> {
        if let Some(dir) = path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        let mut file = match OpenOptions::new().read(true).write(true).create(true).open(path) {
            Ok(f) => f,
            Err(e) => {
                crate::diag_warn!("instance", "打不开单实例锁文件 {}: {e} —— 本次不做重复实例拦截", path.display());
                eprintln!("[instance] 打不开单实例锁文件 {}: {e} —— 本次不做重复实例拦截", path.display());
                return Ok(Inner { file: None });
            }
        };
        match file.try_lock() {
            Ok(()) => {
                // pid 只为了拒绝时能说清"是谁占着";写失败不影响锁本身
                let _ = file.set_len(0);
                let _ = file.seek(SeekFrom::Start(0));
                let _ = write!(file, "{}", std::process::id());
                let _ = file.flush();
                Ok(Inner { file: Some(file) })
            }
            Err(TryLockError::WouldBlock) => {
                let holder = holder_pid(path)
                    .map(|p| format!("pid {p}"))
                    .unwrap_or_else(|| "pid 未知".to_string());
                Err(AlreadyRunning {
                    detail: format!(
                        "已有一个 scrcpy-pad 在运行({holder},锁文件 {})—— 拒绝再起第二个。\n\
                         提示:只关界面窗口不一定结束进程;请结束那个进程后重试。",
                        path.display()
                    ),
                })
            }
            Err(TryLockError::Error(e)) => {
                crate::diag_warn!("instance", "锁定单实例文件 {} 失败: {e} —— 本次不做重复实例拦截", path.display());
                eprintln!("[instance] 锁定单实例文件 {} 失败: {e} —— 本次不做重复实例拦截", path.display());
                Ok(Inner { file: None })
            }
        }
    }

    /// 读出锁文件里记着的 pid(可能为空/半截 —— 读取方不能因此 panic)。
    fn holder_pid(path: &Path) -> Option<u32> {
        let mut text = String::new();
        File::open(path).ok()?.read_to_string(&mut text).ok()?;
        text.trim().parse().ok()
    }
}
