// ============================ Windows:命名互斥体 ============================
#[cfg(windows)]
mod imp {
    use std::ffi::c_void;

    use windows_sys::Win32::Foundation::{
        CloseHandle, ERROR_ALREADY_EXISTS, GetLastError, HANDLE,
    };
    use windows_sys::Win32::System::Threading::CreateMutexW;

    use super::AlreadyRunning;

    /// 为什么带 `Local\` 前缀:输入钩子/隔膜都是**按会话**的东西,不同登录会话
    /// (例如"另一个用户在用同一台机器")各一份是合理的;不加前缀默认也是会话
    /// 命名空间,这里写明是为了让人一眼看懂范围。
    fn full_name(name: &str) -> Vec<u16> {
        format!("Local\\{name}")
            .encode_utf16()
            .chain(std::iter::once(0))
            .collect()
    }

    pub(super) struct Inner {
        /// 互斥体句柄;`null` = 创建失败(退化,放行)。
        handle: HANDLE,
    }

    impl Inner {
        pub(super) fn release(&mut self) {
            if !self.handle.is_null() {
                // SAFETY: 句柄来自本模块的 CreateMutexW,且只在这里关一次。
                unsafe { CloseHandle(self.handle) };
                self.handle = std::ptr::null_mut();
            }
        }
    }

    pub(super) fn acquire_named(name: &str) -> Result<Inner, AlreadyRunning> {
        let wide = full_name(name);
        // SAFETY: 名字是以 NUL 结尾的 UTF-16 缓冲(活得比调用长);不需要
        // SECURITY_ATTRIBUTES(传空 = 默认安全描述符),也不要求初始所有权 ——
        // 我们只用"对象是否已存在"这一位信息,不拿它做同步。
        let handle = unsafe { CreateMutexW(std::ptr::null(), 0, wide.as_ptr()) };
        // **必须紧接在这里读**:任何别的 Win32 调用都可能覆盖 last-error。
        let last = unsafe { GetLastError() };
        if handle.is_null() {
            let e = std::io::Error::last_os_error();
            crate::diag_warn!(
                "instance",
                "创建单实例互斥体失败:{e} —— 本次不做重复实例拦截(拦不住比起不来轻)"
            );
            eprintln!("[instance] 创建单实例互斥体失败:{e} —— 本次不做重复实例拦截");
            return Ok(Inner { handle });
        }
        if last == ERROR_ALREADY_EXISTS {
            // 我们自己刚拿到一个句柄,但它不是"我们该留着的那个":真正的持有者是
            // 仍在跑的那个实例。立刻关掉,免得本进程一退出反而把对象留成孤儿。
            let mut inner = Inner { handle };
            inner.release();
            return Err(AlreadyRunning {
                detail: format!(
                    "已有一个 scrcpy-pad 在运行(命名互斥体 {name} 已存在)—— 拒绝再起第二个。\
                     \n提示:只关界面窗口不一定结束进程;请在任务管理器里结束 scrcpy-pad.exe 后重试。"
                ),
            });
        }
        Ok(Inner { handle })
    }
}
