const LOCK_NAME: &str = "scrcpy-pad-single-instance-v1";

/// "已经有一个实例在跑"。`detail` 是给用户看的人话,直接打 stdout / 诊断日志。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AlreadyRunning {
    pub detail: String,
}

impl std::fmt::Display for AlreadyRunning {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.detail)
    }
}

/// 唯一实例凭据:活着 = 本进程有权继续跑。
///
/// `main` 把它绑在一个活到进程结束的变量上。正常路径上它不会 drop(退出走
/// `std::process::exit`),凭证由内核随进程回收 —— 这正是"守卫自己不是残留"。
pub struct Guard {
    inner: imp::Inner,
}

impl Drop for Guard {
    fn drop(&mut self) {
        // 显式释放:`Inner` 的平台侧句柄才是凭证本体。拒绝路径(创建成功但发现
        // 已存在)也会立刻走同一条释放逻辑,免得本进程反而把对象留成孤儿。
        self.inner.release();
    }
