```rust
/// 默认轨迹最多保留几份(**含本次**这一份)。
const MAX_TRACE_FILES: usize = 3;

/// 只认默认命名的轨迹文件:`trace-<纯数字>.jsonl` -> 那个时间戳。
///
/// 判名字而不是判扩展名:配置目录里还有 profile.yaml / look.json / diagnostics.log,
/// 而**用户自己的文件绝不能被我们删掉**。
fn trace_stamp(name: &str) -> Option<u64> {
    let mid = name.strip_prefix("trace-")?.strip_suffix(".jsonl")?;
    if mid.is_empty() || !mid.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    mid.parse().ok()
}

/// 删掉最旧的默认轨迹文件,让**含本次**的总数不超过 [`MAX_TRACE_FILES`]。
///
/// 只碰 [`trace_stamp`] 认得的文件,且本次要写的 `current` 永不删除
/// (同一秒内重启时它可能已经存在)。清理失败(被占用/只读)只记一行 debug ——
/// 轨迹本身照写:清理是"别无限增长",不是"开不了就别开"。
fn prune_old_traces(current: &Path) {
    let dir = current.parent().unwrap_or_else(|| Path::new("."));
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    let mut old: Vec<(u64, PathBuf)> = Vec::new();
    for entry in entries.flatten() {
        let path = entry.path();
        if path == current {
            continue;
        }
        let Some(name) = path.file_name().and_then(|n| n.to_str()) else {
            continue;
        };
        let Some(stamp) = trace_stamp(name) else {
            continue;
        };
        old.push((stamp, path));
    }
    // 旧的在前。时间戳相同时按路径定序 —— 删哪个必须是确定的,不能看目录顺序。
    old.sort();
    let keep = MAX_TRACE_FILES.saturating_sub(1); // 空位留给本次这一份
    if old.len() <= keep {
        return;
    }
    for (_, path) in old.drain(..old.len() - keep) {
        if let Err(e) = std::fs::remove_file(&path) {
            crate::diag_debug!("trace", "旧轨迹删不掉(不影响本次): {} {e}", path.display());
        }
    }
    crate::diag_debug!(
        "trace",
        "轨迹总量限制:保留最近 {MAX_TRACE_FILES} 份,已删除 {} 份旧轨迹",
        old.len().min(...)
    );
}
```
