        // 提示失败,而不是给出一条假的"检测成功"。
        match imp::acquire_named(LOCK_NAME) {
            Ok(guard) => drop(guard),
            Err(_) => panic!("守卫已被真实实例占用:跑单测前请先关掉正在运行的 scrcpy-pad"),
        }

        let exe = std::env::current_exe().expect("取不到测试程序自身路径");
        let mut child = std::process::Command::new(exe)
            .args(["--exact", "instance::tests::child_holds_guard"])
            .env(CHILD_ENV, "1")
            // 走 null 而不是管道:子进程的输出与我们无关,也不该被管道阻塞
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("子进程起不来");

        // 等子进程真正拿到守卫(最多 5s)。这期间本进程每次尝试都该失败。
        let mut detected = false;
        for _ in 0..200 {
            match imp::acquire_named(LOCK_NAME) {
                // 拿到了 = 子进程还没起好。这个守卫必须**当场放掉** ——
                // 留着不但让子进程拿不到,还会把后续断言变成假阳性。
                Ok(guard) => drop(guard),
                Err(_) => {
                    detected = true;
                    break;
                }
            }
            std::thread::sleep(std::time::Duration::from_millis(25));
        }
        let _ = child.wait();
        assert!(
            detected,
            "另一个进程持有守卫时,本进程必须被拒绝(子进程没起来?过滤名写错了?)"
        );
        assert!(
            imp::acquire_named(LOCK_NAME).is_ok(),
            "持有者退出后守卫必须重新可用:拒绝路径漏关句柄了?内核没回收?"
