/// 这次启动该往哪儿写轨迹。
#[derive(Debug, Clone, PartialEq, Eq)]
enum Choice {
    /// 显式路径(`--trace <路径>` 或 `SCRCPY_PAD_TRACE`)
    Explicit(PathBuf),
    /// 默认位置:配置目录里的 `trace-<时间戳>.jsonl`
    Default,
